/* Super Admin: dashboard, fleet, routes, students, people */
const STC = { 'On Time': '#16a34a', Delayed: '#f59e0b', Stopped: '#ef4444', 'In Maintenance': '#2563eb' };
const FLEET_BUSES = [
  { id: 'GJ01AB1234', x: 362, y: 125, st: 'Stopped', route: 'R-05', delay: '45 min delayed', students: 32, speed: '0 km/h', today: '72 KM' },
  { id: 'GJ01CD5678', x: 165, y: 44, st: 'On Time', route: 'R-02', students: 28, speed: '38 km/h', today: '64 KM' },
  { id: 'GJ01EF9012', x: 433, y: 76, st: 'On Time', route: 'R-03', students: 36, speed: '42 km/h', today: '58 KM' },
  { id: 'GJ01GH3456', x: 218, y: 132, st: 'Delayed', route: 'R-04', delay: '12 min delayed', students: 40, speed: '22 km/h', today: '49 KM' },
  { id: 'GJ01IJ7890', x: 62, y: 190, st: 'On Time', route: 'R-02', students: 30, speed: '35 km/h', today: '61 KM' },
  { id: 'GJ01KL1122', x: 128, y: 218, st: 'Delayed', route: 'R-06', delay: '8 min delayed', students: 24, speed: '18 km/h', today: '44 KM' },
  { id: 'GJ01MN3344', x: 328, y: 218, st: 'On Time', route: 'R-04', students: 40, speed: '40 km/h', today: '70 KM' },
  { id: 'GJ01OP5566', x: 456, y: 268, st: 'In Maintenance', route: '-', students: 0, speed: '0 km/h', today: '0 KM' },
];
function fleetMapSVG(w = 560, h = 330, opts = {}) {
  const sx = w / 560, sy = h / 330, S_ = (x, y) => [Math.round(x * sx), Math.round(y * sy)];
  const selId = opts.sel === undefined ? UI.mapsel : opts.sel;
  const routes = [
    { pts: [[60, 190], [62, 120], [118, 82], [170, 44]].map(p => S_(...p)), c: '#16a34a', w: 3.5 },
    { pts: [[128, 218], [200, 160], [218, 132], [262, 104], [300, 112]].map(p => S_(...p)), c: '#f59e0b', w: 3.5 },
    { pts: [[300, 112], [362, 125], [400, 104], [433, 76]].map(p => S_(...p)), c: '#ef4444', w: 3.5 },
    { id: opts.animId, pts: [[250, 110], [330, 190], [380, 230], [420, 250]].map(p => S_(...p)), c: '#16a34a', w: 3.5 },
  ];
  const markers = FLEET_BUSES.map(b => { const [x, y] = S_(b.x, b.y); return { t: 'badge', x, y, c: STC[b.st], act: opts.noact ? '' : 'mapsel', id: b.id }; });
  if (opts.animId) markers.push({ t: 'bus', x: 0, y: 0, anim: opts.animId, dur: 40, s: 1 });
  const sel = FLEET_BUSES.find(b => b.id === selId);
  if (sel) { const [x, y] = S_(sel.x, sel.y); const v = DATA.vehicles.find(v => v.no === sel.id) || {}; markers.push({ t: 'call', x: Math.min(x + 26, w - 160), y: Math.max(6, y - 10), w: 150, lines: [[`Bus ${sel.id}`, 700, 12], [`Route: ${sel.route}`, 500], sel.delay ? [sel.delay, 600, 11.5, '#dc2626'] : [sel.st, 600, 11.5, STC[sel.st]], [`${sel.students} students on board`, 500], [`Speed: ${sel.speed}`, 500], [`Today: ${sel.today}`, 500]] }); }
  const L = (x, y, t, s, wt) => { const p = S_(x, y); return [p[0], p[1], t, s, wt]; };
  return mapSVG({ w, h, seed: 101, labels: [L(108, 40, 'Raysan'), L(226, 46, 'PDPU'), L(300, 46, 'Infocity'), L(425, 28, 'Adalaj'), L(56, 74, 'Sargasan'), L(196, 120, 'Sargasn', 11), L(510, 112, 'Akshardham'), L(246, 198, 'Gandhinagar', 15, 700, '#1f2937'), L(46, 232, 'Infocity', 11), L(524, 262, 'Koba'), L(34, 276, 'Pethapur'), L(304, 284, 'Infocity'), L(90, 140, 'PDPU', 11)], routes, markers });
}
ACT.mapsel = d => { UI.mapsel = UI.mapsel === d.id ? null : d.id; refresh(); };

